{
  "understanding": {
    "purpose": "Help passengers find a flight and check its departure time, gate and current status.",
    "reading": "Readers scan flight identifiers or destinations to find a row, then read across it; scheduled and estimated times also invite comparison.",
    "groups": [
      "Flight and Destination identify the departure.",
      "Scheduled and Estimated are paired times whose differences reveal delays.",
      "Gate and Status give the immediate boarding information."
    ],
    "keep_intact": [
      "Flight identifiers, times and gate identifiers should remain readable as complete units.",
      "Status words and column headers should ideally remain intact."
    ],
    "may_wrap": [
      "Destination names can wrap at spaces, especially longer airport names.",
      "Multiword statuses can wrap at spaces; rows already made taller by destination wrapping can absorb this."
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [78, 120, 98, 98, 55, 100],
      "idea": "Use a spacious scrolling table with matched time columns and room for destination and status phrases to wrap naturally."
    },
    {
      "name": "B",
      "widths": [62, 103, 98, 94, 55, 89],
      "idea": "Minimize horizontal scrolling while preserving the longest unbreakable words and giving destinations and statuses room to wrap at spaces."
    },
    {
      "name": "C",
      "widths": [55, 75, 62, 62, 43, 62],
      "idea": "Fit the viewport without horizontal scrolling, accepting split headers and words as well as potentially tall rows."
    }
  ]
}
